#!/usr/bin/env python3
"""Package the transmit-region boards into a versioned folder releases/TX_<REV>/ with a hash manifest and, per board, the checks that passed and the items still UNVERIFIED.
Refuses to run if: the sign-off (data/results/SIGNOFF_STATUS.json) has a FAIL or is missing; data/ is stale against work/ (scripts/publish_data.py --check); the release folder already exists
(new versions get new names). The release copies from the COMMITTED data/ folders, so it holds exactly what is in the repository.
usage: release_tx.py REV      e.g. r1 -> releases/TX_r1"""
import sys, os, json, shutil, subprocess, datetime, glob, csv, hashlib
rev = sys.argv[1] if len(sys.argv) > 1 else "r1"; out = f"{os.environ.get('ARX_RELEASE_ROOT', 'releases')}/TX_{rev}"      # ARX_RELEASE_ROOT / ARX_SIGNOFF_JSON: overrides used only by tests/release_signoff_controls.py
def die(m): print("release-tx REFUSED:", m); sys.exit(1)
if os.path.exists(out): die(f"{out} exists: new versions get new names")
SJ = os.environ.get("ARX_SIGNOFF_JSON", "data/results/SIGNOFF_STATUS.json")
try: S = json.load(open(SJ))
except Exception: die(f"{SJ} missing: run make signoff")
if S["counts"]["FAIL"]: die(f"the sign-off has {S['counts']['FAIL']} FAIL")
if subprocess.run([sys.executable, "scripts/publish_data.py", "--check"], capture_output=True).returncode: die("data/ is stale against work/: run scripts/publish_data.py (make publish), review, commit, then sign off again")
BOARDS = {   # board -> gerber folder, kicad files, result files, bom/net files
    "PB1R": dict(gerber="data/gerber/PB1R_v4", kicad=["PF233-PB1R_routed.kicad_pcb", "PF233-PB1R_routed.kicad_dru", "PF233-PB1R_placed.kicad_pcb"], results=["route_PB1R.json", "drc_PB1R.json", "kicad_drc_PB1R.json", "gerber_edge_PB1R.json", "gerber_plane_PB1R.json", "pb1r_check.json", "PF233-PB1R_BOM.csv", "PF233-PB1R_pickplace.csv", "PF233-PB1R.net"]),
    "CB1D": dict(gerber="data/gerber/CB1D_C2", kicad=["PF233-CB1D_routed.kicad_pcb", "PF233-CB1D_routed.kicad_dru"], results=["route_CB1D.json", "drc_CB1D.json", "kicad_drc_CB1D.json", "gerber_hv_CB1D.json", "gerber_edge_CB1D.json", "wiring_audit.json", "trigger_check.json"]),
    "TXJ1": dict(gerber="data/gerber/TXJ1_v2", kicad=["TXJ1.kicad_pcb", "TXJ1.kicad_dru"], results=["kicad_drc_TXJ1.json", "tx_system.json"]),
    "PM2": dict(gerber="data/gerber/PM2_B", kicad=["PF233-PM2_routed.kicad_pcb", "PF233-PM2_routed.kicad_dru", "PF233-PM2_placed.kicad_pcb"], results=["route_PM2.json", "drc_PM2.json", "kicad_drc_PM2.json", "gerber_edge_PM2.json", "power_dock_check.json"]),
    "HB2": dict(gerber="data/gerber/HB2_B", kicad=["PF233-HB2_routed.kicad_pcb", "PF233-HB2_routed.kicad_dru", "PF233-HB2_placed.kicad_pcb"], results=["route_HB2.json", "drc_HB2.json", "kicad_drc_HB2.json", "gerber_edge_HB2.json", "trigger_check.json"]),
    "AU1": dict(gerber="data/gerber/AU1", kicad=["PF233-AU1_routed.kicad_pcb", "PF233-AU1_routed.kicad_dru"], results=["route_AU1.json", "drc_AU1.json", "kicad_drc_AU1.json", "gerber_edge_AU1.json", "au1_check.json"]),
}
SHARED = ["tx_vbus.json", "TX_ONTIME_LUT.csv", "SYSTEM_STRESS_MARGINS.csv", "system_budget.json", "SIGNOFF_STATUS.json",
          "fab_margin_audit.json", "pad_orient_check.json", "fw_timeline.json", "pf233_timing.h", "system_live.json"]   # r5: margins, KiCad pad check, firmware timing header, system model
unv = S["unverified"]; os.makedirs(out)
def cp(src, dst):
    if not os.path.exists(src): return False
    os.makedirs(os.path.dirname(dst), exist_ok=True); shutil.copy(src, dst); return True
summary = []
for b, spec in BOARDS.items():
    d = f"{out}/{b}"; n = 0
    if spec["gerber"] and os.path.isdir(spec["gerber"]):
        for f in sorted(glob.glob(spec["gerber"] + "/*")): n += cp(f, f"{d}/gerber/{os.path.basename(f)}")
    for k in spec["kicad"]: n += cp(f"data/kicad/{k}", f"{d}/kicad/{k}")
    for r in spec["results"]: n += cp(f"data/results/{r}", f"{d}/results/{r}")
    st = S["boards"].get(b, {}); lines = [f"# {b}: checks in this release (generated by scripts/release_tx.py from data/results/SIGNOFF_STATUS.json)", "", f"Sign-off table at the commit being released. Tool-checked / MODELED only; nothing built or measured.", "", "| check | state | detail |", "|---|---|---|"]
    for c, v in st.items(): lines.append(f"| {c} | {v['state']} | {v['detail']} |")
    lines += ["", "## Still UNVERIFIED (docs/UNVERIFIED.md)", ""] + [f"- {k}: {t}" for k, t in unv.items()]
    open(f"{d}/CHECKS.md", "w").write("\n".join(lines) + "\n")
    states = [v["state"] for v in st.values()]; summary.append((b, n, states.count("PASS"), states.count("UNVERIFIED"), spec["gerber"] is not None))
for r in SHARED: cp(f"data/results/{r}", f"{out}/shared/{r}")
cp("data/seed/harness/HARNESS_MASTER_v5.csv", f"{out}/shared/HARNESS_MASTER_v5.csv")   # r5: the wiring the boards are cut for (W066 LED_CLK)
cp("docs/STATUS.md", f"{out}/STATUS.md"); cp("docs/UNVERIFIED.md", f"{out}/UNVERIFIED.md"); cp("docs/design/FAB_RULES.md", f"{out}/FAB_RULES.md")
git = subprocess.run(["git", "rev-parse", "HEAD"], capture_output=True, text=True).stdout.strip()
md = [f"# Transmit-region release TX_{rev}", "", f"Commit {git}; {datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%d %H:%M UTC')}. MODELED / tool-checked only. Not fabricated, not measured, not reviewed by a fabricator.", "",
      "| board | files | checks PASS | UNVERIFIED | Gerber/drill |", "|---|---|---|---|---|"] + [f"| {b} | {n} | {p} | {u} | {'yes' if g else 'no (placed only)'} |" for b, n, p, u, g in summary] + \
     ["", "Per-board check lists are in `<board>/CHECKS.md`; hashes in `MANIFEST.csv`. Boards without Gerbers are placed but not routed (UNVERIFIED rows)."]
open(f"{out}/RELEASE.md", "w").write("\n".join(md) + "\n")
subprocess.run([sys.executable, "scripts/manifest.py", f"{out}/MANIFEST.csv", out], check=True)
print(f"release-tx: {out} written; boards: " + ", ".join(f"{b} ({n} files)" for b, n, *_ in summary))
